    add('fixed_warning','S',30,[8,8],{hidden:true});event(105,'ultimate_lock');
    add('fall','A',6,[9,10],{hidden:true});event(135,'ultimate_fall');
    add('impact','A',8,[10,10],{hidden:true});event(141,'ultimate_impact');
